import pandas as pd, numpy as np
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.units import cm
from reportlab.lib.styles import ParagraphStyle
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Image, Table, TableStyle, PageBreak, KeepTogether
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
D = "/usr/share/fonts/truetype/dejavu/"
pdfmetrics.registerFont(TTFont("DV", D+"DejaVuSans.ttf")); pdfmetrics.registerFont(TTFont("DVB", D+"DejaVuSans-Bold.ttf"))
pdfmetrics.registerFontFamily("DV", normal="DV", bold="DVB")
R = pd.read_pickle("output/R.pkl")
NAVY = colors.HexColor("#1f3b57")
S = lambda n, **k: ParagraphStyle(n, fontName=k.pop("f", "DV"), **k)
body = S("b", fontSize=9.2, leading=13.2, spaceAfter=5); small = S("s", fontSize=7.8, leading=10.5, textColor=colors.HexColor("#444444"))
h1 = S("h1", f="DVB", fontSize=14, leading=18, textColor=NAVY, spaceBefore=8, spaceAfter=6)
h2 = S("h2", f="DVB", fontSize=10.5, leading=14, textColor=NAVY, spaceBefore=6, spaceAfter=3)
bul = S("bul", fontSize=9.2, leading=13, leftIndent=12, bulletIndent=2, spaceAfter=3)
cell = S("c", fontSize=8, leading=10); cellb = S("cb", f="DVB", fontSize=8, leading=10, textColor=colors.white)
P = lambda t, s=body: Paragraph(t, s)
B = lambda t: Paragraph(t, bul, bulletText="•")
def tbl(rows, widths, hdr=True):
    data = [[Paragraph(str(c), cellb if (hdr and i == 0) else cell) for c in r] for i, r in enumerate(rows)]
    t = Table(data, colWidths=[w*cm for w in widths], repeatRows=1 if hdr else 0)
    st = [("GRID", (0, 0), (-1, -1), .4, colors.HexColor("#bbbbbb")), ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
          ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#f2f6fa")]),
          ("TOPPADDING", (0, 0), (-1, -1), 3), ("BOTTOMPADDING", (0, 0), (-1, -1), 3)]
    if hdr: st.append(("BACKGROUND", (0, 0), (-1, 0), NAVY))
    t.setStyle(TableStyle(st)); return t
def img(p, w=17): 
    from PIL import Image as PI
    iw, ih = PI.open(p).size; return Image(p, width=w*cm, height=w*cm*ih/iw)
f0 = lambda x: f"{x:,.0f}"; f1 = lambda x: f"{x:,.1f}"; f2 = lambda x: f"{x:,.2f}"

d, out, h1t, prod, st, m = R["desc"], R["out"], R["h1"], R["prod"], R["st"], R["m"]
corr, sp = R["corr"], R["spearman"]
tr_o, tr_r = R["trend_orders"], R["trend_rev"]
y23, y24, y25 = h1t.loc[2023], h1t.loc[2024], h1t.loc[2025]
pct = lambda a, b: (b/a-1)*100
moy = R["moy"]; mon = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"]
top, bot = prod.index[0], prod.index[-1]
best_m, worst_m = m.revenue.idxmax(), m.revenue.idxmin()
hi = R["hi_rows"]; n_hi = len(hi)
story = []

# ---- Title ----
story += [Spacer(1, 3*cm), P("DecodeLabs · Data Analytics Internship · Batch 2026", S("t0", fontSize=10, textColor=colors.grey)),
          P("Project 2: Exploratory Data Analysis (EDA)", S("t1", f="DVB", fontSize=24, leading=30, textColor=NAVY, spaceBefore=6)),
          P("E-commerce Orders Dataset — Patterns, Trends, Distributions and Outliers", S("t2", fontSize=13, leading=18, spaceBefore=4)),
          Spacer(1, .8*cm),
          tbl([["Prepared by", "Manish Chahar"], ["Dataset", f"Dataset_for_Dat__Analytics.xlsx — {R['rows']:,} orders × {R['cols']} columns"],
               ["Period covered", f"{R['date_min']} to {R['date_max']}"], ["Tools", "Python (pandas, NumPy, SciPy, Matplotlib)"],
               ["Reproducibility", "Every number and chart in this report is generated by eda_analysis.py"]], [4, 13], hdr=False),
          Spacer(1, 1*cm), P("<b>Note on currency:</b> the dataset has no currency field, so values are shown as plain numbers. "
          "“Order value” means TotalPrice summed over orders, before cancellations or returns.", small), PageBreak()]

# ---- Executive summary ----
story += [P("1. Executive Summary", h1),
 P("<b>Problem statement.</b> What does this order data look like — how are prices, quantities and order values distributed, "
   "are there trends over time, which values are unusual, and which factors are related to order value?"),
 P("<b>Methodology.</b> Quality checks (duplicates, missing values, arithmetic consistency), descriptive statistics (mean, median, count, spread), "
   "distribution shape (skewness), outlier detection (IQR rule and Z-score), monthly and half-year trend analysis, correlation analysis and "
   "significance tests (ANOVA, chi-square, Mann-Whitney, linear regression) so that we do not call random variation a pattern."),
 P("<b>Key findings.</b>", body),
 B(f"<b>The data is clean.</b> {R['dup_rows']} duplicate rows, {R['total_mismatch']} rows where TotalPrice ≠ Quantity × UnitPrice. The only missing values are "
   f"{R['missing']['CouponCode']} blank CouponCode cells ({R['missing']['CouponCode']/R['rows']*100:.1f}%), which simply mean “no coupon used”."),
 B(f"<b>Order value is right-skewed.</b> Mean {f0(d.loc['TotalPrice','mean'])} is above the median {f0(d.loc['TotalPrice','median'])} (skew {d.loc['TotalPrice','skew']:.2f}). "
   "Use the median to describe a “typical” order."),
 B(f"<b>{n_hi} high-value outliers</b> exist in TotalPrice (above {f0(R['hi_fence'])}). They are genuine, not errors: all are Quantity = 5 at a high unit price."),
 B(f"<b>{R['bad_pct']:.1f}% of orders ({R['bad_n']}) are Cancelled or Returned</b>, holding {R['bad_val_pct']:.1f}% of total order value ({f0(R['bad_val'])})."),
 B(f"<b>Mild downward drift over time.</b> Comparing January–June of each year, orders fell {abs(pct(y23.orders, y25.orders)):.1f}% and order value fell "
   f"{abs(pct(y23.revenue, y25.revenue)):.1f}% from 2023 to 2025, but the monthly trend and the fall in mean order value are <u>not statistically significant</u> at the 5% level."),
 B("<b>Product, coupon, payment method and referral channel show no significant difference in order value</b> (Kruskal-Wallis p between "
   f"{min(R['kw'].values()):.2f} and {max(R['kw'].values()):.2f}), and none predicts whether an order is lost. Order value is driven almost entirely by "
   f"UnitPrice (r = {corr.loc['UnitPrice','TotalPrice']:.2f}) and Quantity (r = {corr.loc['Quantity','TotalPrice']:.2f}) — which is expected, because TotalPrice is calculated from them."),
 P("<b>Recommendations.</b>", body),
 B("Investigate why about 4 in 10 orders end as Cancelled or Returned; this is the single largest business issue visible in the data."),
 B("Report median order value (not just the mean) and track the Jan–Jun decline with more data before acting on it."),
 B("Review the 8 very large orders as potential bulk or VIP buyers, and check that high-value orders get faster fulfilment."),
 B("Fix data capture: TotalPrice does not reflect coupon discounts (see Section 9), so true revenue may be overstated."),
 PageBreak()]

# ---- Data overview ----
story += [P("2. Data Overview and Quality Checks", h1),
 P(f"The file contains <b>{R['rows']:,} orders</b> placed between <b>{R['date_min']}</b> and <b>{R['date_max']}</b> by <b>{R['n_customers']:,}</b> distinct customers "
   f"(only {R['repeat_customers']} customers appear twice; nobody appears more than twice). Columns: OrderID, Date, CustomerID, Product, Quantity, UnitPrice, ShippingAddress, "
   "PaymentMethod, OrderStatus, TrackingNumber, ItemsInCart, CouponCode, ReferralSource, TotalPrice."),
 tbl([["Check", "Result"], ["Duplicate rows / duplicate OrderIDs", f"{R['dup_rows']} / {R['dup_orderid']}"],
      ["Missing values", f"CouponCode only: {R['missing']['CouponCode']} blanks (= no coupon). All other columns complete"],
      ["TotalPrice = Quantity × UnitPrice (rounded to 2 dp)", f"Holds in all {R['rows']:,} rows ({R['total_mismatch']} mismatches)"],
      ["Value ranges", f"Quantity {d.loc['Quantity','min']:.0f}–{d.loc['Quantity','max']:.0f}; ItemsInCart {d.loc['ItemsInCart','min']:.0f}–{d.loc['ItemsInCart','max']:.0f}; "
                       f"UnitPrice {d.loc['UnitPrice','min']:.2f}–{d.loc['UnitPrice','max']:.2f}; no negative or zero values"],
      ["Categorical columns", "Product: 7 values · PaymentMethod: 5 · OrderStatus: 5 · ReferralSource: 5 · CouponCode: 3 + none"]], [6.5, 10.5]),
 Spacer(1, .3*cm),
 P("Because the data is already clean, no rows were removed and no values were changed; every statistic below uses all 1,200 orders.", body)]

# ---- Descriptive stats ----
story += [P("3. Descriptive Statistics (mean, median, count)", h1)]
rows = [["Column", "Count", "Mean", "Median", "Std dev", "Min", "Q1", "Q3", "Max", "Skew"]]
for c in d.index: rows.append([c] + [f0(d.loc[c, "count"])] + [f2(d.loc[c, k]) for k in ["mean", "median", "std", "min", "Q1", "Q3", "max", "skew"]])
story += [tbl(rows, [2.5, 1.6, 1.7, 1.7, 1.6, 1.4, 1.5, 1.7, 1.7, 1.3]), Spacer(1, .2*cm),
 P(f"<b>Reading the table.</b> Quantity, UnitPrice and ItemsInCart are almost perfectly symmetric (skew within ±0.03): mean ≈ median, so the mean is a fair summary. "
   f"TotalPrice is different: skew {d.loc['TotalPrice','skew']:.2f} with the mean {f0(d.loc['TotalPrice','mean']-d.loc['TotalPrice','median'])} above the median. "
   f"This happens because a large UnitPrice multiplied by a large Quantity produces a long right tail. The top 10% of orders hold {R['top10_share']*100:.1f}% of total order value.")]
story.append(P("Counts by category", h2))
cr = [["Product", "Orders", "%", "OrderStatus", "Orders", "%"]]
cp_, cs_ = R["cats"]["Product"], R["cats"]["OrderStatus"]
for i in range(7):
    a = cp_.iloc[i]; b = cs_.iloc[i] if i < len(cs_) else None
    cr.append([cp_.index[i], int(a["count"]), f1(a["percent"]), cs_.index[i] if b is not None else "", int(b["count"]) if b is not None else "", f1(b["percent"]) if b is not None else ""])
story.append(tbl(cr, [3, 2, 2, 3.5, 2, 2]))
cr2 = [["Payment", "Orders", "%", "Referral", "Orders", "%", "Coupon", "Orders", "%"]]
cpay, cref, ccp = R["cats"]["PaymentMethod"], R["cats"]["ReferralSource"], R["cats"]["CouponCode"]
for i in range(5):
    r_ = [cpay.index[i], int(cpay.iloc[i]["count"]), f1(cpay.iloc[i]["percent"]), cref.index[i], int(cref.iloc[i]["count"]), f1(cref.iloc[i]["percent"])]
    r_ += [ccp.index[i], int(ccp.iloc[i]["count"]), f1(ccp.iloc[i]["percent"])] if i < len(ccp) else ["", "", ""]
    cr2.append(r_)
story += [Spacer(1, .2*cm), tbl(cr2, [2.6, 1.6, 1.3, 2.4, 1.6, 1.3, 2.4, 1.6, 1.3]), Spacer(1, .2*cm),
 P(f"All categories are close to evenly spread (each product has 13–15% of orders; each status 19–21%). A chi-square test of equal product counts gives p = {R['chi_prod_uniform_p']:.2f}, "
   "i.e. no product is meaningfully more or less popular than another.")]

# ---- Distribution ----
story += [P("4. Distributions", h1), img("charts/1_distributions.png", 14),
 P(f"Quantity is flat across 1–5 (about {R['qty5_share']:.0f}% of orders have exactly 5 units). UnitPrice is roughly uniform between about 11 and 700, and ItemsInCart is bell-shaped around "
   f"{d.loc['ItemsInCart','mean']:.1f}. TotalPrice (bottom right) piles up at low values with a tail running to {f0(d.loc['TotalPrice','max'])}. Dashed line = mean, dotted red = median.")]

# ---- Outliers ----
story += [P("5. Outlier Analysis", h1)]
orow = [["Column", "Lower fence", "Upper fence", "IQR outliers", "|Z| > 3 outliers"]]
for _, r in out.iterrows(): orow.append([r.column, f2(r.lower_fence), f2(r.upper_fence), int(r.iqr_outliers), int(r.z_outliers)])
story += [P("Method: IQR rule (below Q1 − 1.5×IQR or above Q3 + 1.5×IQR) as in the course material, cross-checked with the Z-score rule (|Z| > 3).", body),
          tbl(orow, [3.2, 3, 3, 3, 3.5]), Spacer(1, .2*cm), img("charts/2_boxplots.png", 14)]
hrow = [["OrderID", "Date", "Product", "Qty", "UnitPrice", "TotalPrice", "Status"]]
for _, r in hi.iterrows(): hrow.append([r.OrderID, r.Date.date().isoformat(), r.Product, int(r.Quantity), f2(r.UnitPrice), f2(r.TotalPrice), r.OrderStatus])
story += [KeepTogether([P(f"The {n_hi} outlier orders (TotalPrice above {f0(R['hi_fence'])})", h2), tbl(hrow, [2.6, 2.4, 2.2, 1.2, 2.2, 2.4, 2.4])]), Spacer(1, .2*cm),
 P(f"<b>Verdict: signal, not noise.</b> Each of these orders has Quantity = 5 and a UnitPrice of at least {R['hi_min_unit']:.2f}, and TotalPrice matches Quantity × UnitPrice exactly, so none is a typing error. "
   f"They are legitimate large baskets. Only TotalPrice has outliers: Quantity, UnitPrice and ItemsInCart have none by either method. The IQR rule flags {n_hi} orders while the Z-score rule flags "
   f"{int(out.loc[out.column=='TotalPrice','z_outliers'].iloc[0])}, which is why IQR is preferred for skewed business data. Of the {n_hi} orders, "
   f"{int((hi.OrderStatus.isin(['Cancelled','Returned'])).sum())} were Cancelled or Returned, so their value never became real revenue.")]
story.append(PageBreak())

# ---- Trends ----
story += [P("6. Trends over Time", h1), img("charts/3_monthly_trend.png", 14),
 P(f"Monthly orders average {m.orders.mean():.1f} (range {m.orders.min()}–{m.orders.max()}). The best month by order value was {best_m:%B %Y} ({f0(m.revenue.max())}); "
   f"the weakest was {worst_m:%B %Y} ({f0(m.revenue.min())}). Month-to-month swings are large relative to any trend."),
 P(f"<b>Trend test.</b> A straight line through the 30 monthly points slopes down by {abs(tr_o.slope):.2f} orders per month (p = {tr_o.pvalue:.2f}) and {f0(abs(tr_r.slope))} order value per month "
   f"(p = {tr_r.pvalue:.2f}). Both p-values are above 0.05, so the monthly decline is <b>not statistically significant</b>."),
 P("<b>Why we compare half-years.</b> The data ends on 30 June 2025, so 2025 has only six months. Comparing full-year totals would wrongly show a 50% collapse. The fair comparison is January–June in each year:", body),
 img("charts/4_h1_comparison.png", 14)]
hrow2 = [["Jan–Jun", "Orders", "Order value", "Mean order", "Median order"]]
for y in [2023, 2024, 2025]: hrow2.append([y, int(h1t.loc[y, "orders"]), f0(h1t.loc[y, "revenue"]), f1(h1t.loc[y, "aov_mean"]), f1(h1t.loc[y, "aov_median"])])
story += [tbl(hrow2, [3, 3, 3.5, 3.5, 3.5]), Spacer(1, .2*cm),
 P(f"From Jan–Jun 2023 to Jan–Jun 2025: orders {pct(y23.orders, y25.orders):+.1f}%, order value {pct(y23.revenue, y25.revenue):+.1f}%, mean order value {pct(y23.aov_mean, y25.aov_mean):+.1f}%. "
   f"Testing whether the order-value distribution really changed gives p = {R['aov_t_p']:.3f} (Welch t-test) and p = {R['aov_mw_p']:.2f} (Mann-Whitney). "
   "That is suggestive but <b>not conclusive</b> at the 5% level; it should be monitored as more months arrive."),
 P(f"<b>Seasonality (tentative).</b> Average orders per calendar month, adjusted for how many years each month appears in the data: "
   + ", ".join(f"{mon[i]} {moy.iloc[i]:.1f}" for i in range(12)) + f". June is highest and January–February lowest, but with only 2–3 years of data this could be chance, so treat it as a hypothesis. "
   f"Orders are spread evenly across weekdays (chi-square p = {R['dow_p']:.2f}).")]
story.append(PageBreak())

# ---- Relationships ----
story += [P("7. Relationships and Segments", h1), img("charts/6_correlation.png", 14)]
story += [P(f"<b>Correlation.</b> TotalPrice correlates with UnitPrice (r = {corr.loc['UnitPrice','TotalPrice']:.2f}), Quantity (r = {corr.loc['Quantity','TotalPrice']:.2f}) and ItemsInCart "
   f"(r = {corr.loc['ItemsInCart','TotalPrice']:.2f}). Spearman rank correlations agree ({sp.loc['UnitPrice','TotalPrice']:.2f}, {sp.loc['Quantity','TotalPrice']:.2f}, {sp.loc['ItemsInCart','TotalPrice']:.2f}). "
   f"The first two are by construction (TotalPrice = Quantity × UnitPrice). The only non-trivial link is Quantity ↔ ItemsInCart (r = {corr.loc['Quantity','ItemsInCart']:.2f}); "
   f"UnitPrice is unrelated to Quantity (r = {corr.loc['UnitPrice','Quantity']:.2f}) and to ItemsInCart (r = {corr.loc['UnitPrice','ItemsInCart']:.2f}). "
   "<b>Correlation is not causation</b> — a link between Quantity and ItemsInCart does not show that one causes the other.", body)]
prow = [["Product", "Orders", "Units", "Order value", "Mean order", "Median order"]]
for p_, r in prod.iterrows(): prow.append([p_, int(r.orders), int(r.units), f0(r.revenue), f0(r.mean_order), f0(r.median_order)])
story += [P("Product performance (sorted by order value)", h2), tbl(prow, [3, 2, 2, 3.2, 3, 3.2]), Spacer(1, .2*cm),
 P(f"{top} leads on order value ({f0(prod.revenue.iloc[0])}) and {bot} is lowest ({f0(prod.revenue.iloc[-1])}), but the gap reflects both fewer orders and a lower mean order value, and neither difference is statistically significant. "
   f"Order value does not differ significantly between products (Kruskal-Wallis p = {R['kw']['Product']:.2f}), coupon groups ({R['kw']['Coupon']:.2f}), payment methods ({R['kw']['PaymentMethod']:.2f}) or referral channels ({R['kw']['ReferralSource']:.2f}); a one-way ANOVA agrees for product ({R['anova_prod_p']:.2f}) and coupon ({R['anova_coupon_p']:.2f}). "
   "So product ranking differences here should not be over-interpreted.")]
story += [img("charts/5_product_status.png", 14)]
srow = [["OrderStatus", "Orders", "% of orders", "Order value"]]
for s_, r in st.sort_values("orders", ascending=False).iterrows(): srow.append([s_, int(r.orders), f1(r.pct_orders), f0(r.value)])
story += [KeepTogether([tbl(srow, [4, 3, 3.5, 4])]), Spacer(1, .2*cm),
 P(f"<b>Order outcomes.</b> Cancelled ({int(st.loc['Cancelled','orders'])}) and Returned ({int(st.loc['Returned','orders'])}) together are {R['bad_pct']:.1f}% of orders. Grouping status as lost (Cancelled or Returned) vs not lost, the share lost does not differ significantly "
   f"by product (chi-square p = {R['lost_p']['Product']:.2f}), payment method ({R['lost_p']['PaymentMethod']:.2f}), coupon ({R['lost_p']['Coupon']:.2f}) or referral channel ({R['lost_p']['ReferralSource']:.2f}). "
   f"Referral source versus the five detailed statuses gives p = {R['chi_ref_status_p']:.3f}; this is the only nominally significant result of the tests run, but it is one of several tests and disappears when statuses are grouped, "
   "so it is likely a chance pattern and is not used for any recommendation.")]
story.append(PageBreak())

# ---- Key observations ----
story += [P("8. Key Observations — the “So What?” Test", h1)]
orows = [["What the data says", "Business meaning"],
 [f"Mean order value {f0(d.loc['TotalPrice','mean'])} vs median {f0(d.loc['TotalPrice','median'])}; skew {d.loc['TotalPrice','skew']:.2f}", "Report the median as the typical order; the mean is pulled up by a few large baskets."],
 [f"{R['bad_n']} of {R['rows']:,} orders ({R['bad_pct']:.1f}%) are Cancelled/Returned, worth {f0(R['bad_val'])}", f"About {R['bad_val_pct']:.0f}% of booked order value is at risk. Fixing cancellations and returns is the biggest lever."],
 [f"{n_hi} orders above {f0(R['hi_fence'])}, all Quantity = 5", "Genuine bulk buyers. Treat as a segment to protect, not as errors to delete."],
 [f"Jan–Jun orders {pct(y23.orders, y25.orders):+.1f}%, order value {pct(y23.revenue, y25.revenue):+.1f}% (2023→2025); not significant", "A warning sign to monitor, not yet proof of decline."],
 ["Product, coupon, payment and referral show no significant difference in order value or in the share of lost orders", "Order value is driven by price × quantity, not by marketing or payment choices in this data."],
 ["x", "Possible mid-year peak; verify with more years before planning stock or campaigns."]]
orows[-1][0] = f"June average {moy.loc[6]:.1f} orders vs January {moy.loc[1]:.1f}"
story += [tbl(orows, [8.2, 8.8]), Spacer(1, .4*cm), P("9. Limitations and Honest Caveats", h1),
 B("<b>Coupons are not reflected in price.</b> TotalPrice equals Quantity × UnitPrice exactly even for orders with SAVE10, WINTER15 or FREESHIP codes, so discounts are not recorded; real revenue may be lower."),
 B("<b>Cancelled/Returned/Pending orders are included</b> in all order-value totals because the dataset gives no refund amounts. Value figures are gross booked value, not collected revenue."),
 B("<b>2025 covers six months only</b>, so half-year comparisons were used for yearly trends."),
 B("<b>The data looks evenly spread across categories,</b> so many “no difference” results are expected; real-world data would normally show more structure."),
 B("<b>Statistical tests use a 5% significance level.</b> Several tests were run, so a single borderline p-value should not be over-read."),
 B("<b>Descriptive analysis only.</b> No prediction models were built; this is the discovery phase before dashboards or modelling."),
 Spacer(1, .3*cm), P("Appendix: all summary tables are saved as CSV files in the output folder; run <b>python eda_analysis.py</b> to reproduce every number and chart.", small)]

def foot(c, doc):
    c.saveState(); c.setFont("DV", 7.5); c.setFillColor(colors.grey)
    c.drawString(2*cm, 1.1*cm, "DecodeLabs · Data Analytics · Project 2: EDA"); c.drawRightString(A4[0]-2*cm, 1.1*cm, f"Page {doc.page}"); c.restoreState()
SimpleDocTemplate("EDA_Report_Project2.pdf", pagesize=A4, leftMargin=2*cm, rightMargin=2*cm, topMargin=1.8*cm, bottomMargin=1.8*cm,
                  title="Project 2: Exploratory Data Analysis", author="Manish Chahar").build(story, onFirstPage=lambda c, d: None, onLaterPages=foot)
print("ok")
